const taskStops = `-- name: TaskStops :many
SELECT id, task_id, stop_index, destination_raw, destination_hub_id, destination_linked_party_id, status, delivered_at, delivered_lat, delivered_lng, estimated_rate_thb, drop_fee_thb, sequence, added_at, source_id, is_custom FROM task_delivery_stops WHERE task_id = $1 ORDER BY stop_index
`

func (q *Queries) TaskStops(ctx context.Context, taskID uuid.UUID) ([]TaskDeliveryStop, error) {
	rows, err := q.db.Query(ctx, taskStops, taskID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []TaskDeliveryStop{}
	for rows.Next() {
		var i TaskDeliveryStop
		if err := rows.Scan(
			&i.ID,
			&i.TaskID,
			&i.StopIndex,
			&i.DestinationRaw,
			&i.DestinationHubID,
			&i.DestinationLinkedPartyID,
			&i.Status,
			&i.DeliveredAt,
			&i.DeliveredLat,
			&i.DeliveredLng,
			&i.EstimatedRateThb,
			&i.DropFeeThb,
			&i.Sequence,
			&i.AddedAt,
			&i.SourceID,
			&i.IsCustom,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

